/// <summary>
/// PaffH 08.06.21
/// productname should not be editable because NDXProductName1 is used instead
/// </summary>
/// <param name="sender">xFormRun</param>
/// <param name="e">FormEventArgs</param>
[FormEventHandler(formStr(SysTranslationDetail), FormEventType::Initialized),
    SuppressBPWarning('BPParameterNotUsed','e')]
public static void SysTranslationDetail_OnInitialized(xFormRun sender, FormEventArgs e)
{
    const str profileLanguageTranslationText = 'ProfileLanguageTranslation_2';
    FormStringControl formStringControl = sender.design().controlName(profileLanguageTranslationText);
    if (formStringControl)
    {
        formStringControl.allowEdit(false);
    }
}
